import heapq


def _interval_solver(capacity, tie):
    def solve(data):
        jobs = data["jobs"]
        k = data["k"]
        blocked = set(data.get("blocked", []))
        mandatory = set(data.get("mandatory", []))
        quotas = data.get("quotas", {})
        best_value = None
        best_ids = None

        for picked in combinations([j for j in jobs if j["id"] not in blocked], k):
            ids = tuple(sorted(j["id"] for j in picked))
            idset = set(ids)
            if not mandatory.issubset(idset):
                continue
            counts = {}
            for job in picked:
                group = job["group"]
                counts[group] = counts.get(group, 0) + 1
            if any(not low <= counts.get(group, 0) <= high
                   for group, (low, high) in quotas.items()):
                continue

            active = []
            feasible = True
            for job in sorted(picked, key=lambda j: (j["start"], j["end"], j["id"])):
                while active and active[0] <= job["start"]:
                    heapq.heappop(active)
                heapq.heappush(active, job["end"])
                if len(active) > capacity:
                    feasible = False
                    break
            if not feasible:
                continue

            value = sum(j["value"] for j in picked)
            if (best_value is None or value > best_value or
                    (value == best_value and
                     ((tie == "smallest" and ids < best_ids) or
                      (tie == "largest" and ids > best_ids)))):
                best_value, best_ids = value, ids

        if best_value is None:
            return {"error": "impossible"}
        return {"selected": list(best_ids), "value": best_value}
    return solve


def _build_component_06():
    def rounded(numerator, mode):
        if mode == "half_up":
            return (numerator + 5000) // 10000
        return numerator // 10000

    def solve(data):
        cutoff = data.get("cutoff", 10**9)
        chosen = {}
        for position, event in enumerate(data["events"]):
            sequence = event.get("sequence", 0)
            if sequence > cutoff:
                continue
            event_id = event.get("id", "anonymous:" + str(position))
            key = (sequence, event.get("revision", 0), position)
            if event_id not in chosen or key > chosen[event_id][0]:
                chosen[event_id] = (key, event)

        balances = dict(data.get("opening", {}))
        mode = data["rounding"]
        for _, event in chosen.values():
            if event.get("void", False):
                continue
            raw = event["price"] * event.get("quantity", 1)
            discount = min(10000, max(0, event.get("discount_bp", 0)))
            net = rounded(raw * (10000 - discount), mode)
            tax = rounded(raw * event.get("tax_bp", 0), mode)
            amount = net + tax
            if event.get("kind") == "refund":
                amount = -amount
            key = event.get("account", "default") + "|" + event.get("currency", "USD")
            balances[key] = balances.get(key, 0) + amount
        return {"balances": balances}
    return solve


def _build_component_07():
    def solve(data):
        packages = data["packages"]
        names = sorted(packages, reverse=True)
        features = set(data.get("features", []))
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        constraints = {name: [bounds] for name, bounds in data.get("roots", {}).items()}
        required = set(constraints)
        best_versions = None
        best_vector = None

        def acyclic(edges):
            done, active = set(), set()

            def visit(name):
                if name in active:
                    return False
                if name in done:
                    return True
                active.add(name)
                if any(not visit(other) for other in edges.get(name, ())):
                    return False
                active.remove(name)
                done.add(name)
                return True

            return all(visit(name) for name in edges)

        def search(versions, needed, limits, edges):
            nonlocal best_versions, best_vector
            for name, version in versions.items():
                if any(not low <= version <= high for low, high in limits.get(name, ())):
                    return

            pending = needed - versions.keys()
            if not pending:
                if not acyclic(edges):
                    return
                vector = tuple(versions.get(name, -1) for name in names)
                if best_vector is None or vector > best_vector:
                    best_vector = vector
                    best_versions = dict(versions)
                return

            # Branch on the most constrained currently required package.
            choices = []
            for name in pending:
                rows = packages[name]
                allowed = []
                for row in rows:
                    version = row["version"]
                    if any(not low <= version <= high for low, high in limits.get(name, ())):
                        continue
                    if version in blocked.get(name, []):
                        continue
                    if name in pins and version != pins[name]:
                        continue
                    allowed.append(row)
                if not allowed:
                    return
                choices.append((len(allowed), name, allowed))
            _, name, allowed = min(choices, key=lambda item: (item[0], item[1]))

            for row in allowed:
                version = row["version"]
                next_versions = dict(versions)
                next_versions[name] = version
                next_needed = set(needed)
                next_limits = {key: list(value) for key, value in limits.items()}
                next_edges = {key: set(value) for key, value in edges.items()}
                active_deps = [dep for dep in row.get("deps", [])
                               if not dep.get("feature") or dep["feature"] in features]
                next_edges[name] = set()
                valid = True
                for dep in active_deps:
                    other = dep["name"]
                    next_needed.add(other)
                    next_limits.setdefault(other, []).append((dep["min"], dep["max"]))
                    next_edges[name].add(other)
                    if other in next_versions and not dep["min"] <= next_versions[other] <= dep["max"]:
                        valid = False
                        break
                if valid:
                    search(next_versions, next_needed, next_limits, next_edges)

        search({}, required, constraints, {})
        if best_versions is None:
            return {"error": "unsatisfiable"}
        return {"versions": best_versions}
    return solve


def _build_component_08():
    def solve(data):
        required = data.get("required", [])
        bit_for = {node: 1 << i for i, node in enumerate(required)}
        full = (1 << len(required)) - 1
        start_node = data["source"]
        start_mask = bit_for.get(start_node, 0)
        start_state = (start_node, start_mask, 0)
        distances = {start_state: data["start"]}
        queue = [(data["start"], start_node, start_mask, 0)]
        graph = [[] for _ in range(data["n"])]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)

        while queue:
            arrival, node, mask, used = heapq.heappop(queue)
            state = (node, mask, used)
            if distances.get(state) != arrival:
                continue
            if node == data["target"] and mask == full and used == data["coupons"]:
                return {"arrival": arrival}

            for edge in graph[node]:
                depart = max(arrival, edge["open"])
                if depart >= edge["close"]:
                    continue
                options = [(edge["duration"], used)]
                if used < data["coupons"]:
                    duration = max(1, edge["duration"] - edge.get("discount", 0))
                    options.append((duration, used + 1))
                for duration, next_used in options:
                    next_time = depart + duration
                    if next_time > data["deadline"]:
                        continue
                    next_node = edge["v"]
                    next_mask = mask | bit_for.get(next_node, 0)
                    next_state = (next_node, next_mask, next_used)
                    if next_time < distances.get(next_state, float("inf")):
                        distances[next_state] = next_time
                        heapq.heappush(queue, (next_time, next_node, next_mask, next_used))
        return {"arrival": None}
    return solve


